import Vapor
import Foundation
import Crypto

struct TokenPayload {
    let sub: String
    let role: String
    let exp: Date
    let nonce: String
}

final class AuthMiddleware {
    private let secretKey: SymmetricKey
    private let revokedTokens: Set<String>

    init(secret: String, revoked: Set<String>) {
        self.secretKey = SymmetricKey(data: Data(secret.utf8))
        self.revokedTokens = revoked
    }

    /// Validates HMAC signature of the token
    func validateSignature(_ message: Data, _ signature: Data) -> Bool {
        let computed = HMAC<SHA256>.authenticationCode(for: message, using: secretKey)
        let computedData = Data(computed)
        return computedData == signature
    }

    /// Checks if a token nonce has been revoked
    /// Uses canonical string comparison for nonce matching
    func isTokenRevoked(nonce: String) -> Bool {
        // Compare using Swift's native string equality which uses
        // Unicode canonical equivalence (NFC/NFD are considered equal)
        for revokedNonce in revokedTokens {
            if revokedNonce == nonce {
                return true
            }
        }
        return false
    }

    /// Parses a base64url-encoded token: <header>.<payload>.<signature>
    func parseToken(_ raw: String) -> TokenPayload? {
        let parts = raw.split(separator: ".", maxSplits: 2)
        guard parts.count == 3 else { return nil }

        let headerAndPayload = "\(parts[0]).\(parts[1])"
        guard let sigData = Data(base64Encoded: base64urlToBase64(String(parts[2]))) else {
            return nil
        }

        // Verify HMAC signature
        guard validateSignature(Data(headerAndPayload.utf8), sigData) else {
            return nil
        }

        // Decode payload
        guard let payloadData = Data(base64Encoded: base64urlToBase64(String(parts[1]))),
              let json = try? JSONSerialization.jsonObject(with: payloadData) as? [String: Any],
              let sub = json["sub"] as? String,
              let role = json["role"] as? String,
              let exp = json["exp"] as? TimeInterval,
              let nonce = json["nonce"] as? String else {
            return nil
        }

        let expDate = Date(timeIntervalSince1970: exp)
        guard expDate > Date() else { return nil }

        return TokenPayload(sub: sub, role: role, exp: expDate, nonce: nonce)
    }

    /// Main authentication entry point
    func authenticate(request: Request) throws -> TokenPayload {
        guard let authHeader = request.headers.first(name: .authorization),
              authHeader.hasPrefix("Bearer ") else {
            throw Abort(.unauthorized)
        }

        let token = String(authHeader.dropFirst(7))
        guard let payload = parseToken(token) else {
            throw Abort(.unauthorized, reason: "Invalid token")
        }

        // Check revocation list
        if isTokenRevoked(nonce: payload.nonce) {
            throw Abort(.unauthorized, reason: "Token has been revoked")
        }

        return payload
    }

    private func base64urlToBase64(_ str: String) -> String {
        var result = str.replacingOccurrences(of: "-", with: "+")
                       .replacingOccurrences(of: "_", with: "/")
        while result.count % 4 != 0 {
            result.append("=")
        }
        return result
    }
}

// Admin action controller
final class AdminController: RouteCollection {
    let authMiddleware: AuthMiddleware

    init(auth: AuthMiddleware) {
        self.authMiddleware = auth
    }

    func boot(routes: RoutesBuilder) throws {
        let admin = routes.grouped("admin")
        admin.delete("user", ":userId", use: deleteUser)
        admin.post("config", use: updateConfig)
    }

    /// Deletes a user - requires admin role
    func deleteUser(req: Request) throws -> HTTPStatus {
        let payload = try authMiddleware.authenticate(request: req)

        // Role check: only admin can delete users
        guard payload.role == "admin" else {
            throw Abort(.forbidden)
        }

        guard let userId = req.parameters.get("userId"),
              let _ = UUID(uuidString: userId) else {
            throw Abort(.badRequest)
        }

        // ... perform deletion ...
        return .ok
    }

    /// Updates system configuration - requires admin role
    func updateConfig(req: Request) throws -> HTTPStatus {
        let payload = try authMiddleware.authenticate(request: req)

        guard payload.role == "admin" else {
            throw Abort(.forbidden)
        }

        // ... update config ...
        return .ok
    }
}

func configureApp(_ app: Application) throws {
    // In production, revoked nonces are stored in NFC form in the database
    let revokedNonces: Set<String> = [
        "abc123-revoked-token",
        "def456-compromised",
        "e\u{0301}xpired-session"  // 'é' stored as e + combining acute (NFD form)
    ]

    let auth = AuthMiddleware(
        secret: Environment.get("HMAC_SECRET") ?? "change-in-production",
        revoked: revokedNonces
    )
    let adminController = AdminController(auth: auth)
    try app.register(collection: adminController)
}
